const G=2,S=1.1;
const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.70710678,0,0,0.70710678],down:[0.70710678,0,0,0.70710678],right:[0,0,-0.70710678,0.70710678],left:[0,0,0.70710678,0.70710678]};
const dist=s=>(G-s.c)+(G-s.r);
export function initialState(){return {c:0,r:0,moves:0,msg:'Reach the orange goal square.',hint:null};}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const s={...state};
 if(dist(s)===0){s.msg='Goal already reached in '+s.moves+' moves. Press Reset to play again.';return s;}
 const a=event.action;
 if(a==='hint'){s.hint=s.r<G?'up':'right';s.msg='Hint: move '+s.hint+'.';return s;}
 const d=D[a];if(!d)return state;
 const c=s.c+d[0],r=s.r+d[1];
 s.hint=null;
 if(c<0||c>G||r<0||r>G){s.msg="Can't move "+a+': that would leave the board.';return s;}
 s.c=c;s.r=r;s.moves++;
 s.msg=dist(s)===0?'You won in '+s.moves+' moves! The shortest route is 4 moves.':'Moved '+a+'. '+dist(s)+' steps to go.';
 return s;}
export function evaluate({state}){
 const s=state||initialState();
 const x=(s.c-1)*S,z=(1-s.r)*S,k=dist(s);
 const nodes={token:{position:[x,k===0?0.5:0.35,z]},hintArrow:{visible:!!s.hint&&k>0}};
 if(s.hint)nodes.hintArrow.position=[x,0.85,z],nodes.hintArrow.quaternion=Q[s.hint];
 return {nodes,readouts:{steps:k,moves:s.moves},goal:{status:k===0?'won':'playing',message:s.msg}};}
